const posts=[
{cat:'Kubernetes',title:'Що насправді означає «Pod працює»',desc:'Running — лише частина картини. Розбираємо стан контейнера, готовність і роль перевірок здоров’я.',symbol:'⎈',caption:'ORCHESTRATION / K8S',time:5,body:'<p>Статус Running означає, що Pod прив’язаний до вузла, а щонайменше один контейнер працює, запускається або перезапускається. Це ще не гарантує, що застосунок готовий приймати запити.</p><h3>Готовність і життєздатність</h3><p>Readiness probe визначає, чи готовий контейнер обслуговувати трафік. Liveness probe допомагає виявити стан, із якого контейнер не може відновитися самостійно. Startup probe дає повільному застосунку час на запуск.</p><h3>Дивись на систему цілком</h3><p>Перевіряй події Pod, стан контейнерів, логи та конфігурацію Service. Успішна перевірка одного компонента не доводить справність усього шляху запиту.</p>',url:'https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/'},
{cat:'Terraform',title:'Інфраструктура як код: почни з передбачуваності',desc:'Зрозумілий plan, контроль версій і невеликі зміни — основа відтворюваної інфраструктури.',symbol:'{ }',caption:'INFRASTRUCTURE / CODE',time:4,body:'<p>Цінність Infrastructure as Code — у можливості пояснити та відтворити бажаний стан системи. Конфігурація має бути зрозумілою людині, яка переглядатиме зміну.</p><h3>Зміна повинна читатися</h3><p>Зберігай конфігурацію в системі контролю версій. Обмежуй кожну зміну однією метою. Перед застосуванням переглядай plan, особливо операції видалення та заміни ресурсів.</p><h3>Стан — частина системи</h3><p>Terraform state може містити чутливі дані. Обирай сховище з належним контролем доступу та блокуванням, перевіряючи можливості конкретного backend. Не додавай state у публічний репозиторій.</p>',url:'https://developer.hashicorp.com/terraform/language/state'},
{cat:'Docker',title:'Контейнер — тимчасовий. А твої дані?',desc:'Чому життєвий цикл даних варто продумати ще до першого docker compose up.',symbol:'▤',caption:'CONTAINERS / STORAGE',time:4,body:'<p>Дані в writable layer контейнера пов’язані з його життєвим циклом. Для даних, які мають пережити видалення контейнера, передбач окреме сховище.</p><h3>Volume чи bind mount</h3><p>Docker керує volumes, а bind mount пов’язує контейнер із конкретним шляхом на хості. Вибір залежить від вимог до перенесення, доступу та резервування.</p><h3>Перевір відновлення</h3><p>Наявність копії не доводить, що сервіс можна відновити. Перевір процедуру на окремому середовищі. Для баз даних використовуй узгоджений спосіб резервування, який підтримує конкретна СУБД.</p>',url:'https://docs.docker.com/engine/storage/'},
{cat:'Linux',title:'Діагностика Linux: спочатку спостереження',desc:'Як звузити проблему й зберегти докази до того, як перезапуск приховає симптоми.',symbol:'>_',caption:'SYSTEMS / LINUX',time:3,body:'<p>Починай із точного симптому: який запит не проходить, коли це почалося та що змінилося перед збоєм. Формулювання «сервер не працює» занадто широке для діагностики.</p><h3>Від симптому до гіпотези</h3><p>Зістав стан сервісу, його журнал і використання ресурсів. Перевір, чи проблема відтворюється локально, чи виникає тільки через мережу. Фіксуй час подій, щоб співвіднести записи між системами.</p><h3>Одна зміна за раз</h3><p>Перед виправленням визнач очікуваний результат і шлях повернення. Після зміни повтори саме той запит, який демонстрував проблему.</p>',url:'https://www.freedesktop.org/software/systemd/man/latest/journalctl.html'},
{cat:'Homelab',title:'Homelab, у якому є місце для експериментів',desc:'Відокремлюємо навчальні сервіси від тих, від яких залежить щоденне життя.',symbol:'⌂',caption:'SELF-HOSTED / LAB',time:3,body:'<p>Домашня лабораторія корисна, коли дозволяє безпечно помилятися. Якщо кожен експеримент ламає домашній DNS або важливі файли, варто переглянути межі середовища.</p><h3>Почни з залежностей</h3><p>Запиши, де зберігаються дані та які сервіси залежать один від одного. Виділи те, що має бути доступним під час експериментів.</p><h3>Документація як частина лабораторії</h3><p>Зберігай конфігурацію та порядок відновлення. У нотатках відрізняй перевірений результат від плану. Резервні копії перевіряй окремо від основного хоста.</p>'},
{cat:'CI/CD',title:'Pipeline, якому можна довіряти',desc:'Невеликі кроки, один артефакт і зрозумілий результат кожного етапу доставки.',symbol:'⇢',caption:'AUTOMATION / DELIVERY',time:4,body:'<p>Pipeline має робити шлях від зміни коду до розгортання зрозумілим. Для кожного етапу важливо знати вхідні дані, очікуваний результат і причину зупинки.</p><h3>Збирай один раз</h3><p>Пов’язуй артефакт із конкретною ревізією коду. Просувай той самий артефакт між середовищами, якщо це підтримує твоя архітектура, замість непомітного повторного складання.</p><h3>Після deploy робота триває</h3><p>Перевір доступність і ключові сценарії застосунку після розгортання. Успішне завершення команди deploy саме по собі не підтверджує справність сервісу. Заздалегідь визнач спосіб повернення до попереднього стану.</p>'}
];let category='Усі статті';const filters=document.querySelector('#filters'),grid=document.querySelector('#grid'),search=document.querySelector('#search'),reader=document.querySelector('#reader');for(const cat of ['Усі статті',...new Set(posts.map(p=>p.cat))]){let b=document.createElement('button');b.textContent=cat;b.onclick=()=>{category=cat;render()};filters.append(b)}function render(){[...filters.children].forEach(b=>{b.classList.toggle('active',b.textContent===category);b.setAttribute('aria-pressed',b.textContent===category)});const items=posts.map((p,i)=>({...p,i})).filter(p=>(category==='Усі статті'||p.cat===category)&&(p.title+' '+p.desc+' '+p.cat).toLowerCase().includes(search.value.toLowerCase()));grid.innerHTML=items.map(p=>`<a href="#post-${p.i}" class="card" data-post="${p.i}"><div class="art art${p.i}" data-caption="${p.caption}"><span class="symbol">${p.symbol}</span></div><div class="cardbody"><div class="meta"><span class="tag">${p.cat.toUpperCase()}</span><span>СТАРТОВА НОТАТКА</span></div><h3>${p.title}</h3><p>${p.desc}</p><div class="cardend"><span>${p.time} хв читання</span><b>Читати ↗</b></div></div></a>`).join('');document.querySelector('#count').textContent=`${items.length} / ${posts.length} нотаток`;document.querySelector('#empty').hidden=items.length>0}function route(){const m=location.hash.match(/^#post-(\d+)$/);if(m&&posts[+m[1]]){const p=posts[+m[1]];document.querySelector('#article').innerHTML=`<p class="eyebrow">${p.cat.toUpperCase()} / СТАРТОВА НОТАТКА</p><h2>${p.title}</h2>${p.body}${p.url?`<p><a href="${p.url}" target="_blank" rel="noopener noreferrer">Офіційна документація ↗</a></p>`:''}`;if(!reader.open)reader.showModal()}else if(reader.open)reader.close()}document.querySelector('.close').onclick=()=>{location.hash='articles'};reader.addEventListener('click',e=>{if(e.target===reader){const r=reader.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)location.hash='articles'}});reader.addEventListener('cancel',e=>{e.preventDefault();location.hash='articles'});search.addEventListener('input',render);window.addEventListener('hashchange',route);render();route();
